<a href="<?=e(url('/admin/membership-applications'))?>">&larr; Review queue</a><div class="d-flex justify-content-between my-3"><h1 class="h2"><?=e($application['application_number'])?></h1><span class="badge text-bg-primary align-self-center"><?=e($statuses->label($application['status']))?></span></div><div class="row g-4"><div class="col-lg-8"><div class="card shadow-sm mb-4"><div class="card-body"><h2 class="h4">Applicant profile</h2><dl class="row"><dt class="col-sm-4">Name / email</dt><dd class="col-sm-8"><?=e($application['name'])?> | <?=e($application['email'])?></dd><dt class="col-sm-4">Telephone / province</dt><dd class="col-sm-8"><?=e($application['telephone']??'Not provided')?> | <?=e($application['province_name']??'Not provided')?></dd><dt class="col-sm-4">Profession</dt><dd class="col-sm-8"><?=e($application['profession_name']??'Not provided')?></dd><dt class="col-sm-4">Membership type</dt><dd class="col-sm-8"><?=e($application['membership_type_name'])?> - Fee to be confirmed.</dd></dl><p class="small text-secondary">Reviewers cannot edit profiles here.</p><?php if($application['decision_reason']):?><div class="alert alert-info"><strong>Applicant-visible reason:</strong> <?=e($application['decision_reason'])?></div><?php endif;?><?php if($application['internal_note']):?><div class="alert alert-secondary"><strong>Private reviewer note:</strong> <?=e($application['internal_note'])?></div><?php endif;?></div></div><div class="card"><div class="card-body"><h2 class="h4">Timeline</h2><ul class="list-group"><?php foreach($events as $event):?><li class="list-group-item"><strong><?=e($statuses->label($event['new_status']))?></strong> | <?=e(date('j M Y, H:i',strtotime($event['created_at'])))?><?php if($event['note']):?><div><?=e($event['note'])?></div><?php endif;?></li><?php endforeach;?></ul></div></div></div>
<div class="col-lg-4"><div class="card shadow-sm"><div class="card-body"><h2 class="h5">Review action</h2><?php if($application['status']==='submitted'):?><form method="post" action="<?=e(url('/admin/membership-applications/'.$application['application_number'].'/start-review'))?>"><?=csrf_field()?><button class="btn btn-primary w-100">Start review</button></form><?php elseif($application['status']==='under_review'):?><form method="post" action="<?=e(url('/admin/membership-applications/'.$application['application_number'].'/approve'))?>" onsubmit="return confirm('Approve this application?')"><?=csrf_field()?><label for="approve_note">Private note (optional)</label><textarea class="form-control mb-3" id="approve_note" name="internal_note" maxlength="2000"></textarea><button class="btn btn-success w-100">Approve</button></form><hr><form method="post" action="<?=e(url('/admin/membership-applications/'.$application['application_number'].'/reject'))?>" onsubmit="return confirm('Reject this application?')"><?=csrf_field()?><label for="reason">Applicant-visible reason</label><textarea class="form-control mb-3" id="reason" name="decision_reason" maxlength="1000" required></textarea><label for="internal_note">Private internal note</label><textarea class="form-control mb-3" id="internal_note" name="internal_note" maxlength="2000"></textarea><button class="btn btn-danger w-100">Reject</button></form><?php else:?><p>No review transition is available.</p><?php endif;?></div></div></div></div>
